cryptoWire.h1_f:
pt = CBOR{v:1, jehaipyre, ombohovái_pe?, rosca_id?, imandu'a?, oñemondo_pe}
ct = AES-GCM-256-Encriptar (koty_clave, nonce, pt, aad = hex (koty_id))
alambre = CBOR{
  v: 1, 1.1.
  ciphertext: hex (ct), // ipukukue iñambuéva
  nonce: hex(12 B), 1.1.
  omondova’ekue_pseudo: hex (16 B), .
  oñemondo_pe: unix_ms
} .

cryptoWire.h5_f:
okápe = CBOR{
  nodo_fuente: hex32, 1.1.
  mba’e’apohára_destino: int64, .
  cifrado_pype: byte, .
  hyepypegua_nonce: byte, .
  oñemondo_pe: unix_ms
} .
sig = Ed25519-Sign (fuente_priv, okápe)
POST /federación/entrega { sobre: okápe, sig: hex64 }

